import { World, Vec3, Body, Box, Plane, Material, ContactMaterial } from 'cannon-es';

const world = new World({ gravity: new Vec3(0, -9.82, 0) });
world.allowSleep = true;

const groundMaterial = new Material('ground');
const crateMaterial = new Material('crate');
world.addContactMaterial(new ContactMaterial(groundMaterial, crateMaterial, {
  friction: 0.55,
  restitution: 0.08
}));

const groundBody = new Body({ mass: 0, material: groundMaterial });
groundBody.addShape(new Plane());
groundBody.quaternion.setFromEuler(-Math.PI / 2, 0, 0);
world.addBody(groundBody);

const crateBody = new Body({
  mass: 4,
  material: crateMaterial,
  position: new Vec3(0, 4, 0),
  allowSleep: true
});
crateBody.addShape(new Box(new Vec3(0.5, 0.5, 0.5)));
crateBody.linearDamping = 0.02;
world.addBody(crateBody);

export function stepPhysics(deltaSeconds) {
  world.step(1 / 60, deltaSeconds, 5);
