import { World, Vec3, Body, Box, Sphere, Material, ContactMaterial, HingeConstraint } from 'cannon-es';

const world = new World({ gravity: new Vec3(0, -9.82, 0) });
const gateMaterial = new Material('gate');
const ballMaterial = new Material('ball');
world.addContactMaterial(new ContactMaterial(gateMaterial, ballMaterial, {
  friction: 0.4,
  restitution: 0.15
}));

const pivotBody = new Body({ mass: 0, position: new Vec3(1, 1, 0) });
world.addBody(pivotBody);

const gateBody = new Body({
  mass: 12,
  material: gateMaterial,
  position: new Vec3(2, 1, 0)
});
gateBody.addShape(new Box(new Vec3(1, 1, 0.08)));
world.addBody(gateBody);

const hinge = new HingeConstraint(pivotBody, gateBody, {
  pivotA: new Vec3(0, 0, 0),
  pivotB: new Vec3(-1, 0, 0),
  axisA: new Vec3(0, 1, 0),
  axisB: new Vec3(0, 1, 0),
  maxForce: 100
});
world.addConstraint(hinge);

const ballBody = new Body({
  mass: 1,
  material: ballMaterial,
  position: new Vec3(2, 1, -2.5)
});
ballBody.addShape(new Sphere(0.18));
ballBody.velocity.set(0, 0, 8);
world.addBody(ballBody);

let motorRemaining = 0;
gateBody.addEventListener('collide', ({ body }) => {
  if (body === ballBody && motorRemaining <= 0) {
    hinge.enableMotor();
    hinge.setMotorSpeed(1.2);
    hinge.setMotorMaxForce(12);
    motorRemaining = 0.75;
  }
});

export function stepPhysics(deltaSeconds) {
  if (motorRemaining > 0) {
    motorRemaining -= deltaSeconds;
    if (motorRemaining <= 0) hinge.disableMotor();
  }
  world.step(1 / 60, deltaSeconds, 5);
}
